//! Private normal-retirement transitions for one actual learning Work.
//! A C request is an owned capability. No count, boolean or decoded message
//! can construct the returned terminal/ACK/real-join owner facts.

use super::*;
use codex_hepta_learning_artifacts::LearningIterationCoordinatorV1;
use codex_hepta_learning_artifacts::LearningIterationSnapshotV1;
use crate::circuit_learning_delivery::OriginalDurableLearningAcknowledgement;
use crate::circuit_task::OriginalSameActorCQuiescence;

pub(super) struct OriginalLearningRetirement {
    state: Mutex<OriginalLearningRetirementState>,
    changed: Notify,
}

enum OriginalLearningRetirementState {
    Open,
    Requested(Box<OriginalSameActorCQuiescence>),
    Taken,
    StopAuthorized(Box<LearningIterationSnapshotV1>),
    StopTaken,
}

/// Created only by consuming the one stop state authorized by the actual
/// C capability and original durable delivery ACK.
pub(crate) struct OriginalLearningStop {
    work: Arc<OriginalSameActorLearningWork>,
    snapshot: LearningIterationSnapshotV1,
}

/// Only the normal join path creates this after admission is closed and every
/// retained real handle has joined, every output was delivered, and every job
/// holder has released custody.
pub(crate) struct OriginalLearningWorkJoined {
    work: Arc<OriginalSameActorLearningWork>,
}

impl OriginalLearningRetirement {
    pub(super) fn new() -> Self {
        Self {
            state: Mutex::new(OriginalLearningRetirementState::Open),
            changed: Notify::new(),
        }
    }
}

impl OriginalSameActorLearningWork {
    pub(crate) fn require_original_retirement_identity(
        &self,
        identity: &AgentdIdentity,
        gate: &Arc<SameActorPhaseGate>,
    ) -> Result<(), AgentdError> {
        if self.context.identity() != identity || !Arc::ptr_eq(self.gate(), gate) {
            self.gate().close();
            return Err(refused("retired learning Work has another original phase or identity"));
        }
        self.gate().require_open().map(|_| ()).map_err(refused)
    }

    pub(crate) fn require_original_delivery_request(
        &self,
        request: &codex_hepta_learning_artifacts::LearningIterationRequestV1,
        owners: &codex_hepta_learning_artifacts::LearningIterationOwnersV1,
    ) -> Result<(), AgentdError> {
        self.require_original_retirement_identity(self.context.identity(), self.gate())?;
        if request != &self.prepared.initial().request
            || owners != &self.prepared.initial().owners
        {
            self.gate().close();
            return Err(refused("delivery request differs from original Prepared"));
        }
        self.prepared.scope().validate_request(request, owners).map_err(refused)
    }

    pub(crate) fn require_original_terminal_snapshot(
        &self,
        snapshot: &LearningIterationSnapshotV1,
    ) -> Result<(), AgentdError> {
        self.require_original_retirement_identity(self.context.identity(), self.gate())?;
        if snapshot.request != self.prepared.initial().request
            || snapshot.owners != self.prepared.initial().owners
        {
            self.gate().close();
            return Err(refused("terminal checkpoint differs from its original Prepared"));
        }
        self.prepared.scope().validate_snapshot(snapshot).map_err(refused)?;
        let coordinator = LearningIterationCoordinatorV1::from_snapshot(snapshot.clone())
            .map_err(refused)?;
        if coordinator.next_stage().is_some() {
            self.gate().close();
            return Err(refused("original learning checkpoint is not terminal"));
        }
        Ok(())
    }

    pub(crate) fn request_original_normal_retirement(
        self: &Arc<Self>,
        quiescence: OriginalSameActorCQuiescence,
    ) -> Result<(), AgentdError> {
        let mut closing = self.original_failure_scope();
        self.require_identity_and_gate(self.context.identity(), self.gate())?;
        OriginalSameActorCQuiescence::require_original_phase(
            &quiescence, self.context.identity(), self.gate(),
        )?;
        OriginalSameActorCQuiescence::require_original_learning_work(&quiescence, self)?;
        let mut state = self.retirement.state.lock().map_err(refused)?;
        if !matches!(*state, OriginalLearningRetirementState::Open) {
            return Err(refused("original C retirement request was already used"));
        }
        *state = OriginalLearningRetirementState::Requested(Box::new(quiescence));
        drop(state);
        self.retirement.changed.notify_waiters();
        self.gate().notify_original_waiters();
        closing.disarm();
        Ok(())
    }

    pub(crate) async fn take_original_normal_retirement(
        self: &Arc<Self>,
    ) -> Result<OriginalSameActorCQuiescence, AgentdError> {
        let mut closing = self.original_failure_scope();
        loop {
            let changed = self.retirement.changed.notified();
            tokio::pin!(changed);
            changed.as_mut().enable();
            self.require_original_retirement_identity(self.context.identity(), self.gate())?;
            let taken = {
                let mut state = self.retirement.state.lock().map_err(refused)?;
                match &*state {
                    OriginalLearningRetirementState::Open => None,
                    OriginalLearningRetirementState::Requested(_) => {
                        let OriginalLearningRetirementState::Requested(original) =
                            std::mem::replace(&mut *state, OriginalLearningRetirementState::Taken)
                        else {
                            return Err(refused("original retirement state changed under its lock"));
                        };
                        Some(*original)
                    }
                    _ => return Err(refused("original C retirement capability was already taken")),
                }
            };
            if let Some(original) = taken {
                OriginalSameActorCQuiescence::require_original_phase(
                    &original, self.context.identity(), self.gate(),
                )?;
                OriginalSameActorCQuiescence::require_original_learning_work(&original, self)?;
                closing.disarm();
                return Ok(original);
            }
            tokio::select! {
                _ = changed => {},
                _ = self.gate().cancelled() => {
                    return Err(refused("original phase closed before C retirement"));
                }
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    self.gate().deadline().instant(),
                )) => return Err(refused("original phase ended before C retirement")),
            }
        }
    }

    pub(crate) fn authorize_original_learning_stop(
        self: &Arc<Self>,
        quiescence: &OriginalSameActorCQuiescence,
        acknowledged: &OriginalDurableLearningAcknowledgement,
    ) -> Result<(), AgentdError> {
        let mut closing = self.original_failure_scope();
        OriginalSameActorCQuiescence::require_original_phase(
            quiescence, self.context.identity(), self.gate(),
        )?;
        OriginalSameActorCQuiescence::require_original_learning_work(quiescence, self)?;
        OriginalDurableLearningAcknowledgement::require_original_work(acknowledged, self)?;
        OriginalSameActorCQuiescence::require_original_learning_snapshot(
            quiescence, acknowledged.snapshot(),
        )?;
        self.require_original_terminal_snapshot(acknowledged.snapshot())?;
        let mut state = self.retirement.state.lock().map_err(refused)?;
        if !matches!(*state, OriginalLearningRetirementState::Taken) {
            return Err(refused("original learning stop was not authorized exactly once"));
        }
        *state = OriginalLearningRetirementState::StopAuthorized(
            Box::new(acknowledged.snapshot().clone()),
        );
        drop(state);
        self.retirement.changed.notify_waiters();
        self.gate().notify_original_waiters();
        closing.disarm();
        Ok(())
    }

    pub(crate) fn original_normal_retirement_change(&self) -> &Notify {
        &self.retirement.changed
    }

    pub(crate) fn take_original_learning_stop(
        self: &Arc<Self>,
    ) -> Result<Option<OriginalLearningStop>, AgentdError> {
        self.require_original_retirement_identity(self.context.identity(), self.gate())?;
        let mut state = self.retirement.state.lock().map_err(|error| {
            self.gate().close();
            refused(error)
        })?;
        if !matches!(*state, OriginalLearningRetirementState::StopAuthorized(_)) {
            return match *state {
                OriginalLearningRetirementState::StopTaken => {
                    self.gate().close();
                    Err(refused("original learning stop was already consumed"))
                }
                _ => Ok(None),
            };
        }
        let OriginalLearningRetirementState::StopAuthorized(snapshot) =
            std::mem::replace(&mut *state, OriginalLearningRetirementState::StopTaken)
        else {
            self.gate().close();
            return Err(refused("original learning stop state changed under its lock"));
        };
        drop(state);
        Ok(Some(OriginalLearningStop { work: Arc::clone(self), snapshot: *snapshot }))
    }

    pub(crate) async fn join_original_normal_work(
        self: &Arc<Self>,
        learning: &crate::learning_iteration::OriginalLearningLoopRetired,
        delivery: &crate::learning_iteration::OriginalLearningDeliveryRetired,
    ) -> Result<OriginalLearningWorkJoined, AgentdError> {
        let mut closing = self.original_failure_scope();
        crate::learning_iteration::OriginalLearningLoopRetired::require_original_work(learning, self)?;
        crate::learning_iteration::OriginalLearningDeliveryRetired::require_original_work(delivery, self)?;
        let result = self.jobs.join_original_normal().await;
        if let Err(error) = result {
            self.gate().close();
            let cleanup = self.close_and_join_original_work().await;
            return Err(refused(match cleanup {
                Ok(()) => error,
                Err(cleanup) => format!("{error}; original fault cleanup: {cleanup}"),
            }));
        }
        self.require_original_retirement_identity(self.context.identity(), self.gate())?;
        crate::learning_iteration::OriginalLearningLoopRetired::require_original_work(learning, self)?;
        crate::learning_iteration::OriginalLearningDeliveryRetired::require_original_work(delivery, self)?;
        closing.disarm();
        Ok(OriginalLearningWorkJoined { work: Arc::clone(self) })
    }
}

impl OriginalLearningStop {
    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        if !Arc::ptr_eq(&self.work, work) {
            self.work.gate().close();
            work.gate().close();
            return Err(refused("original learning stop belongs to another Work"));
        }
        work.require_original_terminal_snapshot(&self.snapshot)
    }

    pub(crate) fn snapshot(&self) -> &LearningIterationSnapshotV1 {
        &self.snapshot
    }
}

impl OriginalLearningWorkJoined {
    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        if !Arc::ptr_eq(&self.work, work) {
            self.work.gate().close();
            work.gate().close();
            return Err(refused("original joined work belongs to another phase"));
        }
        work.require_original_retirement_identity(work.context.identity(), work.gate())
    }
}

fn refused(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::GenerationFenced(error.to_string())
}

//! Retire the actual Learning command owner only after its real terminal
//! checkpoint and durable delivery acknowledgement authorized this stop.
//! The bootstrap, original ports and stage owners remain held in the result.

use super::*;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_learning::OriginalLearningStop;

pub(crate) struct OriginalLearningLoopRetired {
    _closing: CloseSameActorPhaseOnDrop,
    bootstrap: LearningIterationRuntimeBootstrapV1,
    stop: OriginalLearningStop,
}

struct OriginalRetirableLearningAttempt {
    closing: CloseSameActorPhaseOnDrop,
    bootstrap: LearningIterationRuntimeBootstrapV1,
    state: Arc<AgentdState>,
    cancellation: CancellationToken,
    work: Arc<OriginalSameActorLearningWork>,
}

impl OriginalLearningLoopRetired {
    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        OriginalLearningStop::require_original_work(&self.stop, work)?;
        let snapshot = self.stop.snapshot();
        if self.bootstrap.owners != snapshot.owners
            || self.bootstrap.original_q24.is_none()
            || !self.bootstrap.enforce_circuit_admission
            || !matches!(
                self.bootstrap.circuit_delivery_source,
                CircuitLearningSourceV1::OriginalQ24
            )
        {
            work.gate().close();
            return Err(refused("retired Learning bootstrap differs from its terminal owner"));
        }
        // This is the retained immutable scope/ports binding. It does not
        // reopen a stopped lane or request a new current-authority observation.
        self.bootstrap
            .require_frozen_scope(&snapshot.request)
            .map_err(refused)
    }
}

impl LearningIterationRuntimeBootstrapV1 {
    pub(crate) fn run_original_retirable(
        self,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
        work: Arc<OriginalSameActorLearningWork>,
    ) -> impl std::future::Future<Output = Result<OriginalLearningLoopRetired, AgentdError>>
    + Send
    + 'static {
        let attempt = OriginalRetirableLearningAttempt {
            closing: work.original_failure_scope(),
            bootstrap: self,
            state,
            cancellation,
            work,
        };
        async move {
            // An unpolled or cancelled future still owns the ordered guard.
            let mut attempt = attempt;
            let result = LearningIterationRuntimeBootstrapV1::run_original_retirable_commands(
                &mut attempt.bootstrap,
                &attempt.state,
                &attempt.cancellation,
                &attempt.work,
            ).await;
            let stop = match result {
                Ok(stop) => stop,
                Err(error) => {
                    attempt.work.gate().close();
                    let joined = attempt.work.close_and_join_original_work().await;
                    return Err(match joined {
                        Ok(()) => error,
                        Err(join) => refused(format!("{error}; original Learning cleanup: {join}")),
                    });
                }
            };
            if attempt.cancellation.is_cancelled() {
                attempt.work.gate().close();
                let joined = attempt.work.close_and_join_original_work().await;
                return Err(refused(match joined {
                    Ok(()) => "fault cancellation during Learning retirement".into(),
                    Err(join) => format!("fault cancellation during Learning retirement; {join}"),
                }));
            }
            OriginalLearningStop::require_original_work(&stop, &attempt.work)?;
            Ok(OriginalLearningLoopRetired {
                _closing: attempt.closing,
                bootstrap: attempt.bootstrap,
                stop,
            })
        }
    }

    async fn run_original_retirable_commands(
        &mut self,
        state: &Arc<AgentdState>,
        cancellation: &CancellationToken,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<OriginalLearningStop, AgentdError> {
        self.require_identity(state.identity())?;
        work.require_identity_and_gate(state.identity(), work.gate())?;
        let original: &Arc<crate::OriginalCellQ24LearningStageOwnersV1> =
            self.original_q24.as_ref().ok_or_else(|| {
                refused("retirable Learning requires its actual original Q24 aggregate")
            })?;
        OriginalCellQ24LearningStageOwnersV1::require_original_same_actor_work(original, work)
            .map_err(refused)?;
        loop {
            let changed = work.original_normal_retirement_change().notified();
            tokio::pin!(changed);
            changed.as_mut().enable();
            work.require_original_work_entry().map_err(refused)?;
            if cancellation.is_cancelled() {
                return Err(refused("original Learning fault cancellation"));
            }
            if let Some(stop) = work.take_original_learning_stop()? {
                // Receiver::close is the actual admission cut. Existing
                // reservations may still send; recv == None waits for those
                // real permits as well as the existing queue. A late command
                // is refused, never silently counted as drained.
                self.receiver.close();
                let remaining = tokio::select! {
                    _ = cancellation.cancelled() =>
                        return Err(refused("Learning fault cancellation during queue retirement")),
                    _ = work.gate().cancelled() =>
                        return Err(refused("Learning phase closed during queue retirement")),
                    _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                        work.gate().deadline().instant(),
                    )) => return Err(refused("Learning phase ended during queue retirement")),
                    command = self.receiver.recv() => command,
                };
                if let Some(command) = remaining {
                    let _ = command.response.send(Err(
                        LearningIterationRuntimeErrorV1::CommitUncertain,
                    ));
                    return Err(refused("an original Learning reservation survived the terminal cut"));
                }
                OriginalLearningStop::require_original_work(&stop, work)?;
                return Ok(stop);
            }
            let command = tokio::select! {
                _ = cancellation.cancelled() =>
                    return Err(refused("original Learning fault cancellation")),
                _ = work.gate().cancelled() =>
                    return Err(refused("original Learning phase closed")),
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    work.gate().deadline().instant(),
                )) => return Err(refused("original Learning phase ended")),
                _ = changed => continue,
                command = self.receiver.recv() => command,
            };
            let Some(command) = command else {
                return Err(refused("original Learning queue closed without its terminal stop"));
            };
            let LearningIterationCommandV1 {
                mode,
                request,
                mut response,
            } = command;
            if response.is_closed() {
                return Err(refused("original Learning caller disappeared before dispatch"));
            }
            // Keep the original process and original per-request budget. This
            // outer bound is the unchanged receive's absolute phase end.
            let result = {
                let process = tokio::time::timeout_at(
                    tokio::time::Instant::from_std(work.gate().deadline().instant()),
                    self.process_with_deadline(state, *request, mode),
                );
                tokio::pin!(process);
                tokio::select! {
                    _ = cancellation.cancelled() => Err(LearningIterationRuntimeErrorV1::CommitUncertain),
                    _ = work.gate().cancelled() => Err(LearningIterationRuntimeErrorV1::CommitUncertain),
                    _ = response.closed() => Err(LearningIterationRuntimeErrorV1::CommitUncertain),
                    result = &mut process => result
                        .map_err(|_| LearningIterationRuntimeErrorV1::CommitUncertain)
                        .and_then(|result| result),
                }
            };
            if let Err(error) = &result {
                let cause = error.to_string();
                work.gate().close();
                // Dropping the process above ran its original Training and
                // aggregate cancellation guards. Actual handles remain here.
                let joined = work.close_and_join_original_work().await;
                let _ = response.send(result);
                return Err(refused(match joined {
                    Ok(()) => cause,
                    Err(join) => format!("{cause}; original Learning cleanup: {join}"),
                }));
            }
            work.require_original_work_entry().map_err(refused)?;
            if response.send(result).is_err() {
                return Err(refused("original Learning result acknowledgement was lost"));
            }
        }
    }
}

fn refused(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::GenerationFenced(error.to_string())
}

//! Normal retirement of the actual one-request retained-A delivery owner.
//! A local completed flag or cancellation result never constructs the ACK.

use super::*;
use crate::circuit_learning_delivery::OriginalDurableLearningAcknowledgement;
use crate::circuit_learning_delivery::deliver_original_same_actor_ack;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_learning::OriginalSameActorLearningWork;

pub(crate) struct OriginalLearningDeliveryRetired {
    // Drop closes the common Gate before releasing the retained delivery owner.
    _closing: CloseSameActorPhaseOnDrop,
    runtime: CircuitLearningDeliveryRuntimeV1,
    acknowledged: OriginalDurableLearningAcknowledgement,
}

struct OriginalRetirableDeliveryAttempt {
    closing: CloseSameActorPhaseOnDrop,
    runtime: CircuitLearningDeliveryRuntimeV1,
    store: AutomationStore,
    state: Arc<AgentdState>,
    cancellation: CancellationToken,
    work: Arc<OriginalSameActorLearningWork>,
}

impl OriginalLearningDeliveryRetired {
    pub(crate) fn acknowledgement(&self) -> &OriginalDurableLearningAcknowledgement {
        &self.acknowledged
    }

    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        OriginalDurableLearningAcknowledgement::require_original_work(&self.acknowledged, work)?;
        let snapshot = self.acknowledged.snapshot();
        if self.runtime.requests.as_slice() != std::slice::from_ref(&snapshot.request)
            || self.runtime.owners != snapshot.owners
            || !matches!(self.runtime.source, CircuitLearningSourceV1::OriginalQ24)
            || self.runtime.retained_source.is_none()
        {
            work.gate().close();
            return Err(refused("retired delivery owner differs from its actual ACK"));
        }
        Ok(())
    }
}

impl CircuitLearningDeliveryRuntimeV1 {
    pub(crate) fn run_original_retirable(
        self,
        store: AutomationStore,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
        work: Arc<OriginalSameActorLearningWork>,
    ) -> impl std::future::Future<Output = Result<OriginalLearningDeliveryRetired, AgentdError>>
    + Send
    + 'static {
        let attempt = OriginalRetirableDeliveryAttempt {
            closing: work.original_failure_scope(),
            runtime: self,
            store,
            state,
            cancellation,
            work,
        };
        async move {
            // Retain the real runtime and its failure guard even before poll.
            let attempt = attempt;
            let acknowledged = CircuitLearningDeliveryRuntimeV1::run_original_ack(
                &attempt.runtime,
                attempt.store,
                &attempt.state,
                &attempt.cancellation,
                &attempt.work,
            ).await?;
            if attempt.cancellation.is_cancelled() {
                return Err(refused("delivery fault cancellation after durable ACK"));
            }
            OriginalDurableLearningAcknowledgement::require_original_work(
                &acknowledged, &attempt.work,
            )?;
            Ok(OriginalLearningDeliveryRetired {
                _closing: attempt.closing,
                runtime: attempt.runtime,
                acknowledged,
            })
        }
    }

    async fn run_original_ack(
        &self,
        store: AutomationStore,
        state: &Arc<AgentdState>,
        cancellation: &CancellationToken,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<OriginalDurableLearningAcknowledgement, AgentdError> {
        work.require_identity_and_gate(state.identity(), work.gate())?;
        if self.requests.len() != 1
            || !matches!(self.source, CircuitLearningSourceV1::OriginalQ24)
            || state.identity().spawn_generation != self.spawn_generation
        {
            return Err(refused("normal retirement requires the actual retained-A delivery"));
        }
        let source: &Arc<crate::cell_q24_task_ledger::RegisteredCellQ24RetainedSourceV1> =
            self.retained_source.as_ref()
                .ok_or_else(|| refused("actual retained-A source is absent"))?;
        source.observe_retained_learning(state.identity()).await?;
        let request = self.requests[0].clone();
        if &request != source.request() {
            return Err(refused("retained-A delivery request changed"));
        }
        let original_store = source.original_outbox(state.identity(), &request)?;
        // The original retained source selects the same actual outbox as the
        // default worker; an unrelated supplied store cannot replace it.
        drop(store);
        if original_store.owner_agent_id().as_str() != request.agent_id.as_str()
            || state.identity().agent_id.as_str() != request.agent_id.as_str()
        {
            return Err(refused("original delivery outbox or identity changed"));
        }
        work.require_original_delivery_request(&request, &self.owners)?;
        let mut interval = tokio::time::interval(Duration::from_secs(1));
        interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
        loop {
            tokio::select! {
                _ = cancellation.cancelled() => return Err(refused("delivery fault cancellation")),
                _ = work.gate().cancelled() => return Err(refused("original delivery phase closed")),
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    work.gate().deadline().instant(),
                )) => return Err(refused("original delivery phase ended")),
                _ = interval.tick() => {},
            }
            work.require_original_delivery_request(&request, &self.owners)?;
            if require_ready(state).is_err() {
                continue;
            }
            let row = tokio::select! {
                _ = cancellation.cancelled() => return Err(refused("delivery fault cancellation")),
                _ = work.gate().cancelled() => return Err(refused("original delivery phase closed")),
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    work.gate().deadline().instant(),
                )) => return Err(refused("original delivery phase ended")),
                row = original_store.circuit_learning_delivery(request.source_run_id.as_str()) =>
                    row.map_err(|error| refused(format!("original Circuit outbox: {error:?}")))?,
            };
            let Some(row) = row else {
                continue;
            };
            if row.request_digest.is_none() {
                if !state.automation_admission_ready()? {
                    continue;
                }
                // Preserve the original pre-claim Objective/Circuit check as
                // well as the concrete post-claim check inside delivery.
                tokio::select! {
                    _ = cancellation.cancelled() =>
                        return Err(refused("delivery fault cancellation before original claim")),
                    _ = work.gate().cancelled() =>
                        return Err(refused("original delivery phase closed before claim")),
                    _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                        work.gate().deadline().instant(),
                    )) => return Err(refused("original delivery phase ended before claim")),
                    result = AgentdState::require_circuit_learning_source(state, &request) => result?,
                };
            }
            // Attempt exactly once. The original function permits readback
            // for a previous claim; uncertainty never becomes a fresh dispatch.
            let acknowledged = tokio::select! {
                _ = cancellation.cancelled() => return Err(refused("delivery fault cancellation")),
                _ = work.gate().cancelled() => return Err(refused("original delivery phase closed")),
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    work.gate().deadline().instant(),
                )) => return Err(refused("original delivery phase ended")),
                result = deliver_original_same_actor_ack(
                    &original_store, &self.handle, request.clone(), self.owners.clone(),
                    Arc::clone(state), Arc::clone(work),
                ) => result?,
            };
            OriginalDurableLearningAcknowledgement::require_original_work(&acknowledged, work)?;
            return Ok(acknowledged);
        }
    }
}

fn refused(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::GenerationFenced(error.to_string())
}

//! Durable learning acknowledgement from the original concrete delivery.
//! The constructor is private to this module and follows the actual original
//! checkpoint response, durable ACK transaction and exact local retirement.

use super::*;
use std::sync::Arc;
use crate::AgentdError;
use crate::AgentdState;
use crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop;
use crate::same_actor_q24_phase_learning::OriginalSameActorLearningWork;

pub(crate) struct OriginalDurableLearningAcknowledgement {
    _closing: CloseSameActorPhaseOnDrop,
    work: Arc<OriginalSameActorLearningWork>,
    snapshot: LearningIterationSnapshotV1,
    _store: AutomationStore,
}

impl OriginalDurableLearningAcknowledgement {
    pub(crate) fn snapshot(&self) -> &LearningIterationSnapshotV1 {
        &self.snapshot
    }

    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        if !Arc::ptr_eq(&self.work, work) {
            self.work.gate().close();
            work.gate().close();
            return Err(AgentdError::GenerationFenced(
                "durable delivery ACK belongs to another original Work".into(),
            ));
        }
        work.require_original_terminal_snapshot(&self.snapshot)
    }
}

pub(crate) async fn deliver_original_same_actor_ack(
    store: &AutomationStore,
    backend: &LearningIterationHandleV1,
    request: LearningIterationRequestV1,
    owners: LearningIterationOwnersV1,
    state: Arc<AgentdState>,
    work: Arc<OriginalSameActorLearningWork>,
) -> Result<OriginalDurableLearningAcknowledgement, AgentdError> {
    let closing = work.original_failure_scope();
    work.require_identity_and_gate(state.identity(), work.gate())?;
    work.require_original_delivery_request(&request, &owners)?;
    let source_state: Arc<AgentdState> = Arc::clone(&state);
    let source_request = request.clone();
    let source_work: Arc<OriginalSameActorLearningWork> = Arc::clone(&work);
    // This is the existing concrete delivery: its false claim result permits
    // only original readback; success requires next_stage == None, actual
    // acknowledge_circuit_learning and retire_acknowledged_circuit_learning.
    // No receipt-only public entry can construct this owning ACK.
    let snapshot = delivery(
        store,
        Some(backend),
        request,
        owners,
        DeliveryMode::FirstAttempt,
        Some(Box::pin(async move {
            source_work.require_original_work_entry()?;
            AgentdState::require_circuit_learning_source(&source_state, &source_request)
                .await.map_err(|_| Error::WrongScope)?;
            source_work.require_original_work_entry()
        })),
    )
    .await
    .map_err(|error| AgentdError::GenerationFenced(error.to_string()))?;
    work.require_original_terminal_snapshot(&snapshot)?;
    Ok(OriginalDurableLearningAcknowledgement {
        _closing: closing,
        work,
        snapshot,
        _store: store.clone(),
    })
}

//! Return actual retired Learning and Delivery owners only after the same
//! C cut, durable ACK and all original workers have genuinely joined.
//! Fault paths still close first, cancel the original lanes, then await them.

use super::*;
use crate::AgentdIdentity;
use crate::circuit_task::OriginalSameActorCJoined;
use crate::circuit_task::OriginalSameActorCQuiescence;
use crate::learning_iteration::OriginalLearningDeliveryRetired;
use crate::learning_iteration::OriginalLearningLoopRetired;
use crate::same_actor_q24_phase_gate::SameActorPhaseGate;
use crate::same_actor_q24_phase_learning::OriginalLearningWorkJoined;

/// No public constructor, Clone or decoded representation. These fields are
/// the actual returned owners and actual join receipt, retained until Root's
/// separate purpose-bound resource-retirement permission is available.
pub(crate) struct OriginalRetiredLearningOwners {
    _closing: CloseSameActorPhaseOnDrop,
    work: Arc<OriginalSameActorLearningWork>,
    learning: OriginalLearningLoopRetired,
    delivery: OriginalLearningDeliveryRetired,
    joined: OriginalLearningWorkJoined,
}

/// Returned by the real required worker, never stored back into Work. The
/// consumed C capability now holds the removed route attachment and owners.
pub(crate) struct OriginalSameActorLearningJoined {
    original: OriginalSameActorCJoined,
}

struct OriginalRetirableLearningWorker {
    closing: CloseSameActorPhaseOnDrop,
    worker: OriginalSameActorLearningWorker,
    store: AutomationStore,
    state: Arc<AgentdState>,
    cancellation: CancellationToken,
}

impl OriginalRetiredLearningOwners {
    pub(crate) fn require_original_work(
        &self,
        work: &Arc<OriginalSameActorLearningWork>,
    ) -> Result<(), AgentdError> {
        if !Arc::ptr_eq(&self.work, work) {
            self.work.gate().close();
            work.gate().close();
            return Err(refused("retired Learning owners belong to another original Work"));
        }
        // Verify retained origin and actual completed facts only. Stopped
        // lanes are not reopened through an ordinary current-authority query.
        OriginalLearningLoopRetired::require_original_work(&self.learning, work)?;
        OriginalLearningDeliveryRetired::require_original_work(&self.delivery, work)?;
        OriginalLearningWorkJoined::require_original_work(&self.joined, work)
    }
}

impl OriginalSameActorLearningJoined {
    pub(crate) fn require_original_phase(
        &self,
        identity: &AgentdIdentity,
        gate: &Arc<SameActorPhaseGate>,
    ) -> Result<(), AgentdError> {
        OriginalSameActorCJoined::require_original_phase(&self.original, identity, gate)
    }

    pub(crate) fn original_c_joined(&self) -> &OriginalSameActorCJoined {
        &self.original
    }
}

impl OriginalSameActorLearningWorker {
    pub(crate) fn run_original_retirable(
        self,
        store: AutomationStore,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
    ) -> impl std::future::Future<Output = Result<OriginalSameActorLearningJoined, AgentdError>>
    + Send
    + 'static {
        let attempt = OriginalRetirableLearningWorker {
            closing: self.work.original_failure_scope(),
            worker: self,
            store,
            state,
            cancellation,
        };
        async move {
            let mut attempt = attempt;
            let work = Arc::clone(&attempt.worker.work);
            let result = OriginalSameActorLearningWorker::run_original_retirable_lanes(
                attempt.worker,
                attempt.store, attempt.state, attempt.cancellation,
            ).await;
            match result {
                Ok(joined) => {
                    // Actual CJoined and its retained Learning owners already
                    // own failure closure before this outer guard is disarmed.
                    attempt.closing.disarm();
                    Ok(joined)
                }
                Err(error) => {
                    work.gate().close();
                    let cleanup = work.close_and_join_original_work().await;
                    Err(match cleanup {
                        Ok(()) => error,
                        Err(cleanup) => refused(format!(
                            "{error}; original Learning blocking cleanup: {cleanup}",
                        )),
                    })
                }
            }
        }
    }

    async fn run_original_retirable_lanes(
        self,
        store: AutomationStore,
        state: Arc<AgentdState>,
        cancellation: CancellationToken,
    ) -> Result<OriginalSameActorLearningJoined, AgentdError> {
        OriginalSameActorRootContext::require_current(&self.context)?;
        self.work.require_identity_and_gate(state.identity(), self.context.gate())?;
        CircuitLearningDeliveryRuntimeV1::attach_sources(&self.delivery, &state)?;
        let OriginalSameActorLearningWorker {
            context,
            work,
            learning,
            delivery,
            pending,
            _closing: mut closing,
        } = self;
        let stopped = cancellation.child_token();
        let mut learning = Box::pin(LearningIterationRuntimeBootstrapV1::run_original_retirable(
            learning, Arc::clone(&state), stopped.clone(), Arc::clone(&work),
        ));
        let mut delivery = Box::pin(CircuitLearningDeliveryRuntimeV1::run_original_retirable(
            delivery, store.clone(), Arc::clone(&state), stopped.clone(), Arc::clone(&work),
        ));
        let mut successor = Box::pin(PendingSuccessorOwner::run_original_retirable(
            pending, store, state, stopped.clone(), Arc::clone(context.gate()),
        ));
        let mut retirement = Box::pin(work.take_original_normal_retirement());
        let mut learning_result = None;
        let mut delivery_result = None;
        let mut successor_result = None;
        let mut quiescence = None;
        let mut stop_authorized = false;
        let mut successor_stop_requested = false;
        let failed = loop {
            if cancellation.is_cancelled() {
                break Some("original Learning worker received fault cancellation".to_owned());
            }
            if let Err(error) = context.gate().require_open() {
                break Some(format!("original Learning worker phase: {error}"));
            }
            if !stop_authorized {
                if let (Some(original), Some(Ok(delivered))) = (&quiescence, &delivery_result) {
                    let acknowledged = OriginalLearningDeliveryRetired::acknowledgement(delivered);
                    if let Err(error) = work.authorize_original_learning_stop(original, acknowledged) {
                        break Some(format!("original terminal Learning stop: {error}"));
                    }
                    stop_authorized = true;
                }
            }
            if stop_authorized && !successor_stop_requested {
                if let Some(Ok(learning_owner)) = &learning_result {
                    let Some(original) = &quiescence else {
                        break Some("original C quiescence is missing".into());
                    };
                    if let Err(error) = OriginalLearningLoopRetired::require_original_work(
                        learning_owner, &work,
                    ) {
                        break Some(format!("original Learning owner retirement: {error}"));
                    }
                    // The actual Learning receiver has closed and all its
                    // reservations have finished. Only now stop the real C
                    // loop using the drain-authorized local slot token.
                    if let Err(error) =
                        OriginalSameActorCQuiescence::request_original_successor_retirement(original)
                    {
                        break Some(format!("original C local retirement: {error}"));
                    }
                    successor_stop_requested = true;
                }
            }
            if successor_stop_requested
                && learning_result.is_some()
                && delivery_result.is_some()
                && successor_result.is_some()
            {
                break None;
            }
            tokio::select! {
                result = &mut learning, if learning_result.is_none() => {
                    let error = result.as_ref().err().map(ToString::to_string);
                    learning_result = Some(result);
                    if let Some(error) = error {
                        break Some(format!("original Learning lane: {error}"));
                    }
                    if !stop_authorized {
                        break Some("Learning returned without the actual terminal stop".into());
                    }
                }
                result = &mut delivery, if delivery_result.is_none() => {
                    let error = result.as_ref().err().map(ToString::to_string);
                    delivery_result = Some(result);
                    if let Some(error) = error {
                        break Some(format!("original Delivery lane: {error}"));
                    }
                }
                result = &mut successor, if successor_result.is_none() => {
                    let error = result.as_ref().err().map(ToString::to_string);
                    successor_result = Some(result);
                    if let Some(error) = error {
                        break Some(format!("original Successor lane: {error}"));
                    }
                    if !successor_stop_requested {
                        break Some("C worker returned without its actual retirement request".into());
                    }
                }
                result = &mut retirement, if quiescence.is_none() => {
                    match result {
                        Ok(original) => quiescence = Some(original),
                        Err(error) => break Some(format!("original C retirement request: {error}")),
                    }
                }
                _ = cancellation.cancelled() =>
                    break Some("original Learning worker received fault cancellation".into()),
                _ = context.gate().cancelled() =>
                    break Some("original Learning worker phase closed".into()),
                _ = tokio::time::sleep_until(tokio::time::Instant::from_std(
                    context.gate().deadline().instant(),
                )) => break Some("original Learning worker phase ended".into()),
            }
        };
        // This future has no spawned work. Its requested C capability has
        // either moved into quiescence exactly once, or is still held by Work.
        drop(retirement);
        if let Some(primary) = failed {
            context.gate().close();
            stopped.cancel();
            // Poll every still-running actual lane concurrently. In particular
            // Learning cleanup may wait for observer jobs owned by C; waiting
            // for only one lane first would hide that dependency.
            let (learning_done, delivery_done, successor_done) = tokio::join!(
                async {
                    match learning_result.take() {
                        Some(result) => result,
                        None => learning.as_mut().await,
                    }
                },
                async {
                    match delivery_result.take() {
                        Some(result) => result,
                        None => delivery.as_mut().await,
                    }
                },
                async {
                    match successor_result.take() {
                        Some(result) => result,
                        None => successor.as_mut().await,
                    }
                },
            );
            let mut causes = vec![primary];
            if let Err(error) = &learning_done {
                causes.push(format!("Learning joined: {error}"));
            }
            if let Err(error) = &delivery_done {
                causes.push(format!("Delivery joined: {error}"));
            }
            if let Err(error) = &successor_done {
                causes.push(format!("Successor joined: {error}"));
            }
            // Discard any returned original owners before outer fault cleanup
            // can report that the registered blocking work has been released.
            drop((learning_done, delivery_done, successor_done, quiescence));
            return Err(refused(causes.join("; ")));
        }
        let learning = learning_result.take()
            .ok_or_else(|| refused("original Learning owner result is absent"))??;
        let delivery = delivery_result.take()
            .ok_or_else(|| refused("original Delivery owner result is absent"))??;
        let successor = successor_result.take()
            .ok_or_else(|| refused("original C worker join is absent"))??;
        let quiescence = quiescence.take()
            .ok_or_else(|| refused("original C quiescence was not retained"))?;
        if cancellation.is_cancelled() {
            return Err(refused("fault cancellation preceded actual Work retirement"));
        }
        let joined = work.join_original_normal_work(&learning, &delivery).await?;
        if cancellation.is_cancelled() {
            return Err(refused("fault cancellation followed actual Work retirement"));
        }
        let owners = OriginalRetiredLearningOwners {
            _closing: work.original_failure_scope(),
            work: Arc::clone(&work),
            learning,
            delivery,
            joined,
        };
        OriginalRetiredLearningOwners::require_original_work(&owners, &work)?;
        let original = OriginalSameActorCQuiescence::finish_original_successor_join(
            quiescence, successor, owners,
        )?;
        OriginalSameActorCJoined::require_original_phase(
            &original, context.identity(), context.gate(),
        )?;
        closing.disarm();
        Ok(OriginalSameActorLearningJoined { original })
    }
}

fn refused(error: impl std::fmt::Display) -> AgentdError {
    AgentdError::GenerationFenced(error.to_string())
}

//! Components of the actual Work registry, blocking JoinHandles and Unix FDs.
//! No C capability, Training receipt, durable business ACK or Root completion
//! is manufactured here.

use pretty_assertions::assert_eq;

use super::*;

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn normal_join_keeps_the_actual_delivered_owner_and_closes_new_admission() -> anyhow::Result<()> {
    let jobs = jobs()?;
    let (owned, mut peer) = pair()?;
    let job = {
        let admission = jobs.reserve()?;
        let handle = tokio::task::spawn_blocking(move || Ok::<_, ()>(owned));
        admission.retain_original_handle(handle)
    };
    let original = jobs.receive_registered_job(job).await?
        .map_err(|_| anyhow::anyhow!("original result"))?;
    assert_eq!(jobs.pending.load(Ordering::Acquire), 0);
    tokio::time::timeout(WAIT, jobs.join_original_normal()).await?
        .map_err(anyhow::Error::msg)?;
    jobs.gate.require_open()?;
    assert_eq!(peer.try_read(&mut [0]).unwrap_err().kind(), io::ErrorKind::WouldBlock);
    assert!(jobs.reserve().is_err());
    assert!(jobs.gate.require_open().is_err());
    drop(original);
    require_eof(&mut peer).await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn normal_join_refuses_and_drops_an_actual_undelivered_owner() -> anyhow::Result<()> {
    let jobs = jobs()?;
    let (owned, mut peer) = pair()?;
    let job = {
        let admission = jobs.reserve()?;
        let handle = tokio::task::spawn_blocking(move || Ok::<_, ()>(owned));
        admission.retain_original_handle(handle)
    };
    assert!(tokio::time::timeout(WAIT, jobs.join_original_normal()).await?.is_err());
    assert!(jobs.gate.require_open().is_err());
    require_eof(&mut peer).await?;
    assert_eq!(jobs.pending.load(Ordering::Acquire), 1);
    drop(job);
    assert_eq!(jobs.pending.load(Ordering::Acquire), 0);
    assert!(tokio::time::timeout(WAIT, jobs.close_and_join()).await?.is_err());
    Ok(())
}

#[tokio::test(flavor = "multi_thread", worker_threads = 2)]
async fn cancelling_normal_join_retains_the_same_real_blocking_handle_for_cleanup() -> anyhow::Result<()> {
    let jobs = jobs()?;
    let (owned, mut peer) = pair()?;
    let (started, started_rx) = oneshot::channel();
    let (release, release_rx) = mpsc::sync_channel(1);
    let job = {
        let admission = jobs.reserve()?;
        let handle = tokio::task::spawn_blocking(move || {
            let _ = started.send(());
            release_rx.recv().map_err(|_| ())?;
            Ok::<_, ()>(owned)
        });
        admission.retain_original_handle(handle)
    };
    drop(job);
    tokio::time::timeout(WAIT, started_rx).await??;
    let mut normal = Box::pin(jobs.join_original_normal());
    tokio::select! {
        biased;
        result = &mut normal => panic!("normal join returned while actual work was blocked: {result:?}"),
        _ = tokio::task::yield_now() => {},
    }
    drop(normal);
    assert!(jobs.gate.require_open().is_err());
    assert_eq!(jobs.pending.load(Ordering::Acquire), 1);
    assert_eq!(peer.try_read(&mut [0]).unwrap_err().kind(), io::ErrorKind::WouldBlock);
    let mut cleanup = Box::pin(jobs.close_and_join());
    tokio::select! {
        biased;
        result = &mut cleanup => panic!("cleanup returned before the real handle completed: {result:?}"),
        _ = tokio::task::yield_now() => {},
    }
    release.send(())?;
    tokio::time::timeout(WAIT, cleanup).await?
        .map_err(|_| anyhow::anyhow!("actual cleanup failed"))?;
    require_eof(&mut peer).await?;
    assert_eq!(jobs.pending.load(Ordering::Acquire), 0);
    Ok(())
}

